import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { sanitizeFilename, writeFileBestEffort } from "./bestEffortFs.js";
let dir;
beforeEach(() => {
    dir = mkdtempSync(join(tmpdir(), "best-effort-fs-"));
});
afterEach(() => {
    rmSync(dir, { recursive: true, force: true });
});
describe("sanitizeFilename", () => {
    it("replaces path-unsafe characters and falls back to 'item' when empty", () => {
        expect(sanitizeFilename("abc-123_x.json")).toBe("abc-123_x.json");
        expect(sanitizeFilename("a/b:c d")).toBe("a_b_c_d");
        expect(sanitizeFilename("")).toBe("item");
    });
});
describe("writeFileBestEffort", () => {
    it("creates parent directories and writes, and swallows write errors", () => {
        const target = join(dir, "nested", "deep", "file.txt");
        writeFileBestEffort(target, "hello");
        expect(readFileSync(target, "utf8")).toBe("hello");
        // Writing "under" an existing file is impossible (ENOTDIR); it must not throw.
        writeFileSync(join(dir, "blocker"), "x");
        expect(() => writeFileBestEffort(join(dir, "blocker", "child.txt"), "nope")).not.toThrow();
    });
});
